with unpivoted as (select * from (select id, customer_id, shipping_fee, discount, amount from orders) src unpivot (val for kpi in (shipping_fee, discount, amount))) select case when val >= 65 then 'PREMIUM' else 'STANDARD' end as val_tier, sum(case when kpi = 'discount' then val else 0 end) as discount_val, round(sum(val) / nullif(count(case when kpi = 'amount' then 1 end), 0), 2) as val_per_amount, round(avg(val), 2) as avg_val from unpivoted group by case when val >= 65 then 'PREMIUM' else 'STANDARD' end order by val_per_amount desc nulls first;
